function montarPacotes(itens) {
  let W = 0, V = 0, valor = 0; const grandes = [];
  // 31/10/2026 (estudo de frete): refrigerado com peso real — a tabela tinha 2,3–3,2 kg por caixa de placas/tubos de meio
  // (10 placas = 28,75 kg, 3 pacotes, R$ 240 de frete). Caixa de 10 placas ≈ 0,35 kg; isopor de 3 L com gelo ≈ 1,5 kg por envio.
  const temRefrig = itens.some(it => REFRIG.has(it.c));
  if (temRefrig) { W += ISOPOR_KG; V += ISOPOR_VOL; }
  for (const it of itens) {
    const t = FRETE_TAB[it.c];
    let kg = t ? t[0] : 0.5;
    if (REFRIG.has(it.c) && kg >= 2 && !(t && t[1])) kg = REFRIG_KG_CAIXA;
    const vol = t && t[1] ? (t[1] * t[2] * t[3]) / 1000 : kg / 0.25;
    valor += it.v * it.q;
    if (kg > 12) { for (let i = 0; i < it.q; i++) grandes.push({ kg, d: t && t[1] ? [t[1], t[2], t[3]] : [40, 40, 40] }); continue; }
    W += kg * it.q; V += vol * it.q * 1.3;
  }
  const pk = [];
  if (W > 0) {
    const volMax = BOXES[BOXES.length - 1][0] * BOXES[BOXES.length - 1][1] * BOXES[BOXES.length - 1][2] / 1000;
    const n = Math.max(1, Math.ceil(W / 13), Math.ceil(V / volMax));
    const w = W / n, v = V / n;
    let b = BOXES.find(x => x[3] >= w && (x[0] * x[1] * x[2]) / 1000 >= v) || BOXES[BOXES.length - 1];
    for (let i = 0; i < n; i++) pk.push({ kg: w, d: [b[0], b[1], b[2]] });
  }
  for (const g of grandes) pk.push(g);
  return { pk, valor, peso: W + grandes.reduce((s, g) => s + g.kg, 0) };
}


