const REFRIG_MARKUP = 0.50;  // 31/10/2026: acréscimo sobre a cotação só nos refrigerados (ambiente segue MARKUP 30%)
const REFRIG_PRAZO_MAX = 4;  // 3 dias úteis + 1 de postagem
const REFRIG_PRAZO_MAX_VIZ = 5; // 31/10/2026 (Eduardo): MG, ES e PR aceitam 4 dias úteis + 1 — JeT/Buslog em vez do SEDEX de R$ 122
const REFRIG_UF_VIZ = /^(MG|ES|PR)$/;
const REFRIG_UF_BLOQ = /^(AC|AL|AM|AP|MT|PA|PB|PI|RO|RR|SE|TO)$/;
const REFRIG_AEREO = /latam|azul|gol|a[eé]reo|aereo/i;

async function frete2(req, env) {
  let b; try { b = await req.json(); } catch (e) { return { erro: 'entrada' }; }
  const cep = String(b.cep || '').replace(/\D/g, '');
  if (cep.length !== 8 || !Array.isArray(b.itens) || !b.itens.length || b.itens.length > 60) return { erro: 'entrada' };
  const itens = b.itens.map(x => ({ c: String(x.c || '').slice(0, 40), q: Math.max(1, Math.min(9999, parseInt(x.q) || 1)), v: Math.max(0, Number(x.v) || 0) }));
  const { pk, valor, peso } = montarPacotes(itens);
  const extraG = Math.round(itens.filter(it => GREINER.has(it.c)).reduce((s, it) => s + it.v * it.q, 0) * GREINER_TAXA * 100) / 100;
  if (!pk.length || pk.length > MAX_PACOTES) return { opcoes: [], consulta: true };
  const uf = ufDoCep(cep);
  if (uf === 'AC') return { opcoes: [], bloqueado: true, msg: 'Não atendemos o Acre.' };
  let gratis = null;
  const products = pk.map((p, i) => ({
    id: 'p' + i, quantity: 1,
    height: Math.ceil(p.d[0] * MEDIDA_FOLGA), width: Math.ceil(p.d[1] * MEDIDA_FOLGA), length: Math.ceil(p.d[2] * MEDIDA_FOLGA),
    weight: Math.round(p.kg * PESO_FOLGA * 100) / 100, insurance_value: Math.round((valor / pk.length) * 100) / 100
  }));
  const r = await env.FRETE.fetch(new Request(FRETE_URL, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ from: ORIGEM_CEP, to: cep, products }) }));
  let d = await r.json();
  if (d && !Array.isArray(d)) d = (d.price || d.company) ? [d] : [];
  const ok = (d || []).filter(o => o && o.price && !o.error && !BLOQ.test((o.company && o.company.name) || o.name || ''));
  const ops = ok.map(o => ({
    id: String(o.id || ''), nome: (o.company && o.company.name ? o.company.name + ' ' : '') + (o.name || ''),
    prazo: (parseInt(o.delivery_time || (o.delivery_range && o.delivery_range.max)) || 0) + PRAZO_EXTRA,
    preco: Math.round((parseFloat(o.price) * (1 + MARKUP) + extraG) * 100) / 100
  })).sort((a, b) => a.preco - b.preco);
  // Frete grátis: a decisão usa o custo REAL deste CEP (menor cotação ao vivo, já com a folga de peso/medida),
  // e não só a tabela por UF. k = cotação ao vivo / custo da tabela por UF para o mesmo carrinho.
  let kCep = 1;
  try {
    const base = custoFrete(uf, itens);
    if (ops.length && base > 0) kCep = Math.min(4, Math.max(0.8, ((ops[0].preco - extraG) / (1 + MARKUP)) / base));
    gratis = gratisInfo(uf, itens, kCep);
  } catch (e) { gratis = null; }
  if (itens.some(it => REFRIG.has(it.c))) {
    const np = pk.length;
    const prazoMax = REFRIG_UF_VIZ.test(uf || '') ? REFRIG_PRAZO_MAX_VIZ : REFRIG_PRAZO_MAX;
    let rops = REFRIG_UF_BLOQ.test(uf || '') ? [] : ops.filter(o => o.prazo <= prazoMax && !REFRIG_AEREO.test(o.nome) && (uf === 'RJ' || !/jet|j&t/i.test(o.nome)));
    // 31/10/2026: todas as opções do filtro já cabem no prazo do refrigerado; dentro delas vale a mais barata
    // (antes era a mais rápida: para BH saía SEDEX de R$ 113 com JeT de 5 dias a R$ 35 disponível)
    rops.sort((a, b) => a.preco - b.preco || a.prazo - b.prazo);
    // refrigerado: cotação +50% (em vez de +30%) e sem isopor no frete
    rops = rops.slice(0, 1).map(o => Object.assign({}, o, { preco: Math.round((((o.preco - extraG) / (1 + MARKUP)) * (1 + REFRIG_MARKUP) + extraG + ISOPOR * np) * 100) / 100 }));
    let g = { ativo: false, falta: null, sugestoes: [] };
    const locR = entregaLocal(cep);
    try {
      if (!locR && rops.length && itens.every(it => PROD[it.c])) {
        // PROD dos refrigerados ainda está sem os +R$ 8/un de isopor do preço (30/10): soma os 8 no valor e 6,85 líquidos
        let V = 0, N = 0; for (const it of itens) { const r = REFRIG.has(it.c); V += (PROD[it.c][0] + (r ? 8 : 0)) * it.q; N += (PROD[it.c][1] + (r ? 6.85 : 0)) * it.q; }
        const real = (rops[0].preco - extraG - ISOPOR * np) / (1 + REFRIG_MARKUP) + 8; // + R$ 8 de isopor e gelo reais por envio
        if (N - real >= GRATIS_SOBRA * V) { rops[0] = Object.assign({}, rops[0], { gratis: true, economia: rops[0].preco, preco: 0 }); g = { ativo: true }; }
      }
    } catch (e) {}
    if (locR) rops.unshift(locR);
    const out = { opcoes: rops, uf, gratis: g, refrigerado: true, refrigSrv: true };
    if (b.dbg) out.dbg = { prazoMax, ops: ops.map(o => [o.nome, o.preco, o.prazo]), pk };
    return out;
  }
  const sel = ops.slice(0, 3);
  const rapida = ops.slice().sort((a, b) => a.prazo - b.prazo || a.preco - b.preco)[0];
  if (rapida && !sel.includes(rapida)) sel.push(rapida);
  const loc = entregaLocal(cep); if (loc) { sel.unshift(loc); gratis = { ativo: false, local: true }; }
  if (gratis && gratis.ativo && sel.length) { sel[0] = Object.assign({}, sel[0], { preco: 0, gratis: true, economia: sel[0].preco }); }
  return { opcoes: sel, uf, gratis };
}

function cors(req, h) {
  const o = req.headers.get('Origin');
  h.set('Access-Control-Allow-Origin', o && ORIGENS.includes(o) ? o : ORIGENS[0]);
  h.set('Vary', 'Origin');
  h.set('Access-Control-Allow-Methods', 'GET, POST, OPTIONS');
  h.set('Access-Control-Allow-Headers', 'Content-Type');
  h.set('Access-Control-Max-Age', '86400');
  return h;
}

export default {
  async fetch(req, env) {
    const url = new URL(req.url);
    const p = url.pathname.replace(/\/+$/, '');
    if (req.method === 'OPTIONS') return new Response(null, { status: 204, headers: cors(req, new Headers()) });
    let resp;
    try {
      if (p === '/frete2' && req.method === 'POST') {
        const out = await frete2(req, env);
        return new Response(JSON.stringify(out), { status: out.erro ? 400 : 200, headers: cors(req, new Headers({ 'Content-Type': 'application/json', 'Cache-Control': 'no-store' })) });
      } else if (p === '/frete') {
        const t = new URL(FRETE_URL);
        t.search = url.search;
        resp = await env.FRETE.fetch(new Request(t.toString(), req));
      } else if (p === '/versao') {
        const b = new TextEncoder().encode(JSON.stringify([PROD, FRETE_TAB, GRID, SUG]));
        const d = await crypto.subtle.digest('SHA-256', b);
        const hx = Array.from(new Uint8Array(d)).map(x => x.toString(16).padStart(2, '0')).join('').slice(0, 16);
        return new Response(JSON.stringify({ v: '2026-10-20', h: hx, n: Object.keys(PROD).length }), { headers: cors(req, new Headers({ 'Content-Type': 'application/json' })) });
      } else if (p === '/evento' || p === '/rastreio') {
        const t = new URL(SHEET);
        t.search = url.search;
        const init = { method: req.method === 'POST' ? 'POST' : 'GET', redirect: 'follow' };
        if (req.method === 'POST') {
          init.body = await req.text();
          init.headers = { 'Content-Type': 'text/plain;charset=utf-8' };
        }
        resp = await fetch(t.toString(), init);
      } else if (p === '') {
        return new Response('ok', { headers: cors(req, new Headers({ 'Content-Type': 'text/plain' })) });
      } else {
        return new Response('not found', { status: 404, headers: cors(req, new Headers()) });
      }
    } catch (e) {
      return new Response(JSON.stringify({ error: 'proxy' }), { status: 502, headers: cors(req, new Headers({ 'Content-Type': 'application/json' })) });
    }
    const h = new Headers(resp.headers);
    ['access-control-allow-origin', 'access-control-allow-credentials', 'set-cookie', 'content-security-policy', 'x-frame-options'].forEach(k => h.delete(k));
    if (p === '/rastreio') h.set('Content-Type', 'application/javascript; charset=utf-8');
    return new Response(resp.body, { status: resp.status, headers: cors(req, h) });
  }
};
